export function dashboardMessages(locale: DashboardLocale): DashboardMessages { return messages[locale]; }
export function normalizeDashboardLocale(value: string | null | undefined): DashboardLocale { return DASHBOARD_LOCALES.includes(value as DashboardLocale) ? value as DashboardLocale : "fa"; }

